<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Akun Pengurus</title><style>body{font-family:Arial,sans-serif;background:#f7f4ee;color:#171717;margin:0;padding:32px}.box{max-width:1100px;margin:auto;background:#fff;padding:28px;border-radius:16px}form{display:grid;grid-template-columns:1.2fr 1.5fr 1fr 1fr 1fr;gap:10px;margin-bottom:28px}input,select,button{padding:11px;border:1px solid #ddd;border-radius:7px;font:inherit}button{background:#171717;color:#fff;cursor:pointer}.admin{padding:15px 0;border-bottom:1px solid #ddd}.message{padding:12px;background:#ecfdf5;color:#166534;margin-bottom:18px}.role{font-weight:700;color:#665600}@media(max-width:800px){form{grid-template-columns:1fr}}:root{--ink:#17201d;--muted:#68736f;--line:#e5e9e6;--soft:#f7f9f6;--accent:#d8ff27}body{font-family:Inter,system-ui,sans-serif;background:radial-gradient(circle at 90% 0,#e9f7c8 0,transparent 28%),#f4f7f3;color:var(--ink);padding:42px 34px}.box{border:1px solid var(--line);box-shadow:0 14px 40px #17201d12}.box button{background:var(--ink);border-color:var(--ink);border-radius:10px}.box input,.box select{border-color:var(--line);border-radius:10px}.message{border-radius:10px}html[data-theme="dark"] body{color:#f3f7f4;background:#101412}html[data-theme="dark"] .box{background:#1a211e;border-color:#35413b}html[data-theme="dark"] input,html[data-theme="dark"] select{color:#f3f7f4;background:#202923;border-color:#4a5a50}html[data-theme="dark"] h1,html[data-theme="dark"] p{color:#f3f7f4}</style></head><body><main class="box"><button type="button" id="theme-toggle" style="float:right">☾</button><h1>Super Admin: Kelola Akun Pengurus</h1><p>Atur email, password, role, dan status aktif akun.</p><form method="POST" action="{{ route('logout') }}" style="display:block;margin:0 0 24px">@csrf<button type="submit">Keluar</button></form>@if(session('success'))<div class="message">{{ session('success') }}</div>@endif<form method="POST" action="{{ route('admin.accounts.store') }}">@csrf<input name="name" placeholder="Nama pengurus" required><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Kata sandi" required><select name="role" required><option value="admin">Admin</option><option value="bendahara">Bendahara</option><option value="sekretaris">Sekretaris</option></select><button>Tambah akun</button></form>@foreach($admins as $admin)<form class="admin" method="POST" action="{{ route('admin.accounts.update', $admin) }}">@csrf @method('PATCH')<input name="name" value="{{ $admin->name }}" required><input type="email" name="email" value="{{ $admin->email }}" required><input type="password" name="password" placeholder="Password baru"><select name="role" required><option value="admin" @selected($admin->role === 'admin')>Admin</option><option value="bendahara" @selected($admin->role === 'bendahara')>Bendahara</option><option value="sekretaris" @selected($admin->role === 'sekretaris')>Sekretaris</option></select><select name="active"><option value="1" @selected($admin->active)>Aktif</option><option value="0" @selected(!$admin->active)>Nonaktif</option></select><button>Simpan</button></form>@endforeach<a href="{{ route('admin.dashboard') }}">Kembali ke dashboard</a></main><script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body></html>
